"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["1817"],{5862(e,s,t){t.r(s),t.d(s,{metadata:()=>n,default:()=>c,frontMatter:()=>a,contentTitle:()=>o,toc:()=>d,assets:()=>l});var n=JSON.parse('{"id":"m8-k8s-serving/deep-dive","title":"Deep Dive: Probe Math, Service Backpressure & GPU Serving","description":"The core lab got OpsMate running on Kubernetes and showed you the restart-loop failure mode. This is Part 2 the startupProbe failureThreshold math worked out exactly for a slow loader, what the Service and endpoints layer really does when the engine queues, the GPU serving concepts you will meet the moment this leaves an 8 GB laptop, and PriorityClass for model pods versus batch \u2014 the M11 setup.","source":"@site/docs/m8-k8s-serving/deep-dive.md","sourceDirName":"m8-k8s-serving","slug":"/m8-k8s-serving/deep-dive","permalink":"/305-llmops/docs/m8-k8s-serving/deep-dive","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"sidebar_position":4,"title":"Deep Dive: Probe Math, Service Backpressure & GPU Serving","sidebar_label":"Deep Dive (Part 2)"},"sidebar":"courseSidebar","previous":{"title":"Quiz: Serving on Kubernetes \u2014 Capacity, the Artifact Chain & Probes","permalink":"/305-llmops/docs/m8-k8s-serving/quiz"},"next":{"title":"Lesson: Serving Patterns \u2014 Canary Routing, KServe & llm-d","permalink":"/305-llmops/docs/m9-serving-patterns/lesson"}}'),r=t(4848),i=t(8453);let a={sidebar_position:4,title:"Deep Dive: Probe Math, Service Backpressure & GPU Serving",sidebar_label:"Deep Dive (Part 2)"},o="Deep Dive \u2014 Probe Math, Service Backpressure & GPU Serving",l={},d=[{value:"startupProbe anatomy \u2014 the failureThreshold math, worked exactly",id:"startupprobe-anatomy--the-failurethreshold-math-worked-exactly",level:2},{value:"Service backpressure \u2014 what the endpoints layer does when the engine queues",id:"service-backpressure--what-the-endpoints-layer-does-when-the-engine-queues",level:2},{value:"GPU serving concepts \u2014 the survey you need before this leaves the laptop",id:"gpu-serving-concepts--the-survey-you-need-before-this-leaves-the-laptop",level:2},{value:"ImageVolume \u2014 a newer alternative to the initContainer chain (survey)",id:"imagevolume--a-newer-alternative-to-the-initcontainer-chain-survey",level:2},{value:"PriorityClass and preemption \u2014 model pods versus batch (the M11 setup)",id:"priorityclass-and-preemption--model-pods-versus-batch-the-m11-setup",level:2},{value:"Where you will use this",id:"where-you-will-use-this",level:2}];function h(e){let s={code:"code",em:"em",h1:"h1",h2:"h2",header:"header",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(s.header,{children:(0,r.jsx)(s.h1,{id:"deep-dive--probe-math-service-backpressure--gpu-serving",children:"Deep Dive \u2014 Probe Math, Service Backpressure & GPU Serving"})}),"\n",(0,r.jsxs)(s.p,{children:["The core lab got OpsMate running on Kubernetes and showed you the restart-loop failure mode. This is Part 2: the mechanism underneath. You already operate Kubernetes in production, so none of this re-teaches probes or Services \u2014 it goes to the level you actually reason at when a model pod misbehaves at 2 a.m. and the ordinary Kubernetes intuition gives the wrong answer. Four things: the startupProbe ",(0,r.jsx)(s.code,{children:"failureThreshold"})," math worked out exactly for a slow loader, what the Service and endpoints layer really does when the engine queues, the GPU serving concepts you will meet the moment this leaves an 8 GB laptop, and PriorityClass for model pods versus batch \u2014 the M11 setup."]}),"\n",(0,r.jsx)(s.p,{children:"Everything here runs against the same cluster the lab built. Bring it up if it is down:"}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-bash",children:"make -C labs/opsmate k8s-up\nkubectl --kubeconfig labs/opsmate/k8s/kubeconfig apply -f labs/opsmate/k8s/model-server.yaml\nkubectl --kubeconfig labs/opsmate/k8s/kubeconfig rollout status deployment opsmate-model --timeout=180s\n"})}),"\n",(0,r.jsx)(s.h2,{id:"startupprobe-anatomy--the-failurethreshold-math-worked-exactly",children:"startupProbe anatomy \u2014 the failureThreshold math, worked exactly"}),"\n",(0,r.jsxs)(s.p,{children:["The lesson gave you the rule: ",(0,r.jsx)(s.code,{children:"failureThreshold \xd7 periodSeconds"})," is the load budget. Now the exact anatomy, because getting the boundaries wrong is how a pod that loads in 41 seconds gets killed at second 40."]}),"\n",(0,r.jsx)(s.p,{children:"A startupProbe has four numbers that matter, and they compose into a single deadline:"}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-text",children:"initialDelaySeconds : wait this long AFTER container start before the first probe\nperiodSeconds       : seconds between probes\nfailureThreshold    : consecutive failures allowed before the container is killed\ntimeoutSeconds      : how long ONE probe waits for a response before counting as a failure\n\ntotal grace \u2248 initialDelaySeconds + (failureThreshold \xd7 periodSeconds)\n"})}),"\n",(0,r.jsxs)(s.p,{children:["For OpsMate's manifest \u2014 ",(0,r.jsx)(s.code,{children:"periodSeconds: 5"}),", ",(0,r.jsx)(s.code,{children:"failureThreshold: 30"}),", no ",(0,r.jsx)(s.code,{children:"initialDelaySeconds"})," \u2014 the grace is ",(0,r.jsx)(s.code,{children:"0 + 30 \xd7 5 = 150 seconds"}),'. The model loads in ~40 s, so there are 110 seconds of margin. That margin is not waste; it is the difference between "loads fine on my quiet laptop" and "loads fine on a shared node under memory pressure where the load takes three times as long." Size the startupProbe for the ',(0,r.jsx)(s.em,{children:"worst plausible"})," load time, not the median, because the cost of being generous is a slightly later restart on a genuinely dead pod, while the cost of being tight is killing healthy pods under load."]}),"\n",(0,r.jsxs)(s.p,{children:["The subtle part is what happens at the boundary. The kubelet fires the first probe ",(0,r.jsx)(s.code,{children:"periodSeconds"})," after the container starts (or after ",(0,r.jsx)(s.code,{children:"initialDelaySeconds"})," if set), not at t=0. Each failure increments a counter; the counter resets to zero on the first ",(0,r.jsx)(s.em,{children:"success"}),". When the counter reaches ",(0,r.jsx)(s.code,{children:"failureThreshold"}),", the container is killed and restarted \u2014 and critically, ",(0,r.jsx)(s.strong,{children:"the startupProbe begins again from zero on the restart"}),". So a model that takes just over the budget does not eventually squeak through; it gets killed at the budget, restarts, and takes just over the budget ",(0,r.jsx)(s.em,{children:"again"})," \u2014 the same restart loop as the bad-liveness demo, this time caused by a too-tight startupProbe rather than an aggressive liveness. Prove the timing to yourself by reading the probe config off the live pod:"]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-bash",children:"kubectl --kubeconfig labs/opsmate/k8s/kubeconfig get pod -l app=opsmate-model \\\n  -o jsonpath='{.items[0].spec.containers[0].startupProbe}' | jq .\n"})}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Expected output"})," (the numbers that compose into the 150 s budget)"]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-json",children:'{\n  "failureThreshold": 30,\n  "httpGet": {\n    "path": "/health",\n    "port": "http",\n    "scheme": "HTTP"\n  },\n  "periodSeconds": 5,\n  "successThreshold": 1,\n  "timeoutSeconds": 1\n}\n'})}),"\n",(0,r.jsxs)(s.p,{children:["Note ",(0,r.jsx)(s.code,{children:"timeoutSeconds: 1"})," (the default). One thing people miss: if ",(0,r.jsx)(s.code,{children:"/health"})," is slow to ",(0,r.jsx)(s.em,{children:"respond"})," (not just slow to come up) \u2014 say the engine is thrashing and the HTTP handler takes 2 s \u2014 each probe times out at 1 s and counts as a failure even though the endpoint would have answered. On a memory-starved node that can eat your whole budget. When a slow loader is dying just under the budget, check whether the probes are timing out (raise ",(0,r.jsx)(s.code,{children:"timeoutSeconds"}),") versus genuinely failing (raise ",(0,r.jsx)(s.code,{children:"failureThreshold"}),"), because they have different fixes. Read the actual probe outcomes from the events:"]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-bash",children:"kubectl --kubeconfig labs/opsmate/k8s/kubeconfig get events \\\n  --field-selector involvedObject.kind=Pod -o wide | grep -i probe | head\n"})}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Expected output"})," (on a healthy load, startup probes fail a few times during load then stop \u2014 no kills)"]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-text",children:"LAST SEEN   TYPE      REASON      OBJECT                              MESSAGE\n7m21s       Warning   Unhealthy   pod/opsmate-model-7b657d5cc5-5zqzj  Startup probe failed: HTTP probe failed with statuscode: 503\n"})}),"\n",(0,r.jsxs)(s.p,{children:["Those ",(0,r.jsx)(s.code,{children:"Startup probe failed"})," warnings during the load are ",(0,r.jsx)(s.strong,{children:"normal and expected"})," \u2014 the model is not up yet, so ",(0,r.jsx)(s.code,{children:"/health"})," is not serving traffic (it answers ",(0,r.jsx)(s.code,{children:"503"})," while loading, or refuses the connection outright on a cold start before the port is even bound), and the startupProbe absorbs exactly this. The pod is healthy; the warnings stop the moment the model loads and never escalate to a kill because the count never reaches 30. This is the single most misread signal for model pods: startup-probe warnings during load are the system working, not breaking."]}),"\n",(0,r.jsx)(s.h2,{id:"service-backpressure--what-the-endpoints-layer-does-when-the-engine-queues",children:"Service backpressure \u2014 what the endpoints layer does when the engine queues"}),"\n",(0,r.jsxs)(s.p,{children:["In M3 you watched ",(0,r.jsx)(s.code,{children:"requests_deferred"})," climb under load \u2014 the engine's own queue. Here is the question that matters on Kubernetes: when the engine is saturated and queuing internally, what does the ",(0,r.jsx)(s.em,{children:"Service"})," layer do about it? The honest answer surprises people: ",(0,r.jsx)(s.strong,{children:"by default, nothing."})," And understanding why is what separates a working autoscaling setup (M9/M11) from one that thrashes."]}),"\n",(0,r.jsxs)(s.p,{children:["A Kubernetes Service is a load balancer over the pods that its readinessProbe says are Ready. That is the whole mechanism. It has no idea a pod's engine is internally queuing 40 requests \u2014 it only knows the pod is Ready (passing ",(0,r.jsx)(s.code,{children:"/health"}),") or not. So when your single llama-server pod is at its batch ceiling and deferring requests, the Service keeps routing ",(0,r.jsx)(s.em,{children:"more"})," requests to it, because ",(0,r.jsx)(s.code,{children:"/health"})," still returns 200 \u2014 the engine is alive and loaded, just busy. The queue grows inside the pod, p95 latency climbs (exactly the M3 load-test pattern), and the Service is oblivious."]}),"\n",(0,r.jsx)(s.mermaid,{value:'flowchart LR\n  C["clients"] --\x3e SVC["Service<br/>(routes to READY pods)"]\n  SVC --\x3e|"/health = 200,<br/>so \'Ready\'"| POD["model pod"]\n  POD --\x3e ENG["engine<br/>batch full \u2192<br/>requests_deferred climbs"]\n  ENG -.->|"queue grows,<br/>Service can\'t see it"| SVC\n  ENG --\x3e|"the real signal<br/>lives HERE"| MET["/metrics<br/>requests_deferred"]'}),"\n",(0,r.jsxs)(s.p,{children:["This is why the readinessProbe is a blunt instrument for backpressure and ",(0,r.jsx)(s.code,{children:"/metrics"})," is the sharp one. ",(0,r.jsx)(s.code,{children:"/health"}),' answers "is the engine alive?" \u2014 a binary that stays green under load. ',(0,r.jsx)(s.code,{children:"requests_deferred"}),' answers "is the engine keeping up?" \u2014 the graded signal you actually need. The two are different questions, and conflating them is a classic model-serving mistake. You ',(0,r.jsx)(s.em,{children:"could"})," wire a readiness probe that goes unready when the queue is deep (shedding load by pulling the pod from the Service), but that is a sledgehammer \u2014 an unready pod gets ",(0,r.jsx)(s.em,{children:"zero"}),' traffic, so you have converted "slow" into "down." The production answer is to leave readiness as a liveness-of-serving check and scale on the queue metric, which is precisely what M9 (a second replica) and M11 (autoscaling on ',(0,r.jsx)(s.code,{children:"requests_deferred"}),") build."]}),"\n",(0,r.jsxs)(s.p,{children:["You can see the disconnect live. Drive a small load through the port-forward and watch ",(0,r.jsx)(s.code,{children:"/health"})," stay green while the queue metric moves:"]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-bash",children:"# terminal A: port-forward (leave running)\nkubectl --kubeconfig labs/opsmate/k8s/kubeconfig port-forward service/opsmate-model 8080:8080\n# terminal B: hammer it, then read both signals\nOPENAI_BASE_URL=http://localhost:8080/v1 MODEL=qwen3-0.6b uv run labs/m3/loadtest.py &\nwhile true; do \\\n  printf 'health=%s  ' \"$(curl -s --max-time 2 http://localhost:8080/health | jq -r .status)\"; \\\n  curl -s http://localhost:8080/metrics | grep -E '^llamacpp:requests_(processing|deferred)' | tr '\\n' ' '; echo; \\\n  sleep 0.5; done\n"})}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Expected output"})," (terminal B \u2014 ",(0,r.jsx)(s.code,{children:"health"})," never leaves ",(0,r.jsx)(s.code,{children:"ok"}),"; the queue fills and drains underneath it; the exact ",(0,r.jsx)(s.code,{children:"deferred"})," peak tracks the top concurrency level ",(0,r.jsx)(s.code,{children:"loadtest.py"})," drives)"]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-text",children:"health=ok  llamacpp:requests_processing 0 llamacpp:requests_deferred 0\nhealth=ok  llamacpp:requests_processing 4 llamacpp:requests_deferred 16\nhealth=ok  llamacpp:requests_processing 4 llamacpp:requests_deferred 8\nhealth=ok  llamacpp:requests_processing 4 llamacpp:requests_deferred 2\nhealth=ok  llamacpp:requests_processing 4 llamacpp:requests_deferred 0\n"})}),"\n",(0,r.jsxs)(s.p,{children:["Read it: ",(0,r.jsx)(s.code,{children:"health=ok"})," the entire time, while ",(0,r.jsx)(s.code,{children:"requests_deferred"})," climbed (here to 16 \u2014 ",(0,r.jsx)(s.code,{children:"loadtest.py"})," ramps to concurrency 16 against a batch ceiling of 4, so ~12 requests queue) and then drained. ",(0,r.jsx)(s.code,{children:"requests_processing"})," pins at the batch size the engine can run at once; everything above that waits in ",(0,r.jsx)(s.code,{children:"requests_deferred"}),". The Service saw a healthy pod throughout and kept routing; the only place the saturation showed up was the metric. That is the signal M11's autoscaler watches \u2014 never ",(0,r.jsx)(s.code,{children:"/health"}),"."]}),"\n",(0,r.jsx)(s.h2,{id:"gpu-serving-concepts--the-survey-you-need-before-this-leaves-the-laptop",children:"GPU serving concepts \u2014 the survey you need before this leaves the laptop"}),"\n",(0,r.jsx)(s.p,{children:"This course serves on CPU by design (8 GB, no GPU, no cloud account). But the moment OpsMate goes to real production, it lands on a GPU, and three concepts govern how a model pod gets one. This is a survey \u2014 honest about what you cannot run here, with a recorded-demo pointer \u2014 not a hands-on step."}),"\n",(0,r.jsxs)(s.p,{children:["The first concept is the ",(0,r.jsx)(s.strong,{children:"device plugin"}),". Kubernetes does not natively know what a GPU is; a node's GPUs are advertised to the scheduler by a vendor ",(0,r.jsx)(s.strong,{children:"device plugin"})," (NVIDIA's is the common one) that runs as a DaemonSet and registers a resource like ",(0,r.jsx)(s.code,{children:"nvidia.com/gpu"}),". Once registered, a pod requests a GPU the same way it requests memory:"]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-yaml",children:"resources:\n  limits:\n    nvidia.com/gpu: 1     # request one whole GPU (requests and limits must match for devices)\n"})}),"\n",(0,r.jsxs)(s.p,{children:["The catch that bites people: ",(0,r.jsx)(s.code,{children:"nvidia.com/gpu"})," is an ",(0,r.jsx)(s.em,{children:"integer, non-divisible"})," resource by default. A pod gets a whole GPU or none \u2014 you cannot request ",(0,r.jsx)(s.code,{children:"0.5"}),". For a 0.6B model that uses a fraction of an A100, a whole-GPU-per-pod model is wildly wasteful, which leads to the other two concepts."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Time-slicing"}),' lets multiple pods share one physical GPU by taking turns on it. The device plugin is configured to advertise, say, 4 "replicas" of each GPU, and the scheduler hands them out as if there were four \u2014 but they are the ',(0,r.jsx)(s.em,{children:"same"})," silicon, context-switching between pods. There is no memory isolation and no hard performance guarantee: a heavy pod can starve its neighbors, and one pod's OOM can affect others. Time-slicing is the right tool for many small, bursty, non-critical workloads (dev, batch inference of a tiny model like OpsMate's) where utilization matters more than isolation."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"MIG"})," (Multi-Instance GPU, on A100/H100-class hardware) is the opposite trade: it partitions one physical GPU into up to seven ",(0,r.jsx)(s.em,{children:"hardware-isolated"})," instances, each with its own dedicated memory and compute slice. A pod scheduled onto a MIG instance gets a guaranteed, isolated fraction \u2014 a neighbor cannot starve it. MIG is the right tool when you are packing multiple ",(0,r.jsx)(s.em,{children:"production"})," model services onto expensive GPUs and need each to have predictable performance. The cost is rigidity: the partition profiles are fixed sizes, set at the hardware level, not per-pod."]}),"\n",(0,r.jsx)(s.mermaid,{value:'flowchart TB\n  subgraph WHOLE["whole GPU per pod"]\n    W["1 pod \u2192 1 physical GPU<br/>simple, isolated, wasteful for small models"]\n  end\n  subgraph TS["time-slicing"]\n    T["N pods \u2192 1 GPU, taking turns<br/>high utilization, NO isolation<br/>\u2192 small/bursty/non-critical work"]\n  end\n  subgraph MIG["MIG"]\n    M["1 GPU \u2192 up to 7 isolated instances<br/>hardware-guaranteed slices<br/>\u2192 multiple production services, predictable"]\n  end'}),"\n",(0,r.jsxs)(s.p,{children:["The decision rule: whole-GPU for a single large latency-critical model that fills the card; time-slicing for many small non-critical pods where you are chasing utilization; MIG when you need multiple isolated production tenants on one expensive GPU. OpsMate's 0.6B model would run under time-slicing in a dev cluster and its own MIG instance in production. The ",(0,r.jsx)(s.strong,{children:"recorded GPU serving demo"})," in this module's video section walks a real vLLM pod requesting ",(0,r.jsx)(s.code,{children:"nvidia.com/gpu"})," on a cloud node, so you see the device-plugin path end to end without needing a GPU on your desk."]}),"\n",(0,r.jsx)(s.h2,{id:"imagevolume--a-newer-alternative-to-the-initcontainer-chain-survey",children:"ImageVolume \u2014 a newer alternative to the initContainer chain (survey)"}),"\n",(0,r.jsxs)(s.p,{children:["The lab's initContainer-plus-PVC pattern is deliberate, not the only option \u2014 Kubernetes has since added a more direct primitive worth knowing about, even though this lab does not validate it. ",(0,r.jsx)(s.strong,{children:"ImageVolume"})," (a Kubernetes volume type, stable in current Kubernetes) mounts an OCI artifact straight into a pod as a read-only volume, no initContainer required:"]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-yaml",children:"volumes:\n  - name: model-weights\n    image:\n      reference: registry.local:5100/opsmate/model:1.0.0\n"})}),"\n",(0,r.jsxs)(s.p,{children:["The kubelet pulls, caches, and garbage-collects the artifact the same way it already handles container images \u2014 using the same pull secrets and mirror config your initContainer's ",(0,r.jsx)(s.code,{children:"kit unpack"})," needed the ",(0,r.jsx)(s.code,{children:"hostAliases"})," fix for. The design explicitly covers this course's exact case (an OCI artifact carrying model weights, not a runnable container), which means the ",(0,r.jsx)(s.em,{children:"same signed ModelKit from M7"})," \u2014 the one your initContainer chain unpacks by hand \u2014 could, in principle, mount directly, with the kubelet doing the pull/cache/GC instead of a hand-authored init step."]}),"\n",(0,r.jsxs)(s.p,{children:["This is a survey line, not a validated lab step: whether it mounts a KitOps ModelKit's specific artifact layout without modification is untested on this course's KIND setup, and it is worth confirming on your own cluster before relying on it. What it removes, if it works, is exactly the two-paths registry wall this lab made you hit on purpose \u2014 the initContainer's own HTTP call is the thing that needed ",(0,r.jsx)(s.code,{children:"hostAliases"}),"; a kubelet-native image pull uses the same path as every other image pull in the cluster and does not. That is the trade to weigh: the initContainer pattern is explicit and debuggable (you can ",(0,r.jsx)(s.code,{children:"kubectl exec"})," into it, read its logs, see exactly what it did), while ImageVolume is more automatic but more opaque as a newer primitive. Know both; the lab teaches the one that lets you see every step the first time."]}),"\n",(0,r.jsx)(s.h2,{id:"priorityclass-and-preemption--model-pods-versus-batch-the-m11-setup",children:"PriorityClass and preemption \u2014 model pods versus batch (the M11 setup)"}),"\n",(0,r.jsxs)(s.p,{children:['Last piece, and it sets up M11. On a shared cluster your latency-critical model server competes for node capacity with everything else \u2014 batch jobs, CI runners, cron work. When the node fills, which pod wins? By default it is arbitrary, and "arbitrary" means your production model server can be evicted so a batch job can schedule. ',(0,r.jsx)(s.strong,{children:"PriorityClass"})," fixes that."]}),"\n",(0,r.jsxs)(s.p,{children:["A PriorityClass assigns a numeric priority to pods. When the scheduler cannot place a high-priority pod for lack of capacity, it will ",(0,r.jsx)(s.strong,{children:"preempt"})," (evict) lower-priority pods to make room. Define two classes \u2014 a high one for serving, a low one for batch:"]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-bash",children:'kubectl --kubeconfig labs/opsmate/k8s/kubeconfig apply -f - <<\'EOF\'\napiVersion: scheduling.k8s.io/v1\nkind: PriorityClass\nmetadata:\n  name: model-serving\nvalue: 1000000            # high \u2014 production inference must not be evicted\nglobalDefault: false\ndescription: "Latency-critical model servers. Preempts batch when the node is full."\n---\napiVersion: scheduling.k8s.io/v1\nkind: PriorityClass\nmetadata:\n  name: batch-inference\nvalue: 1000              # low \u2014 preemptible; yields to serving under pressure\nglobalDefault: false\ndescription: "Best-effort batch. Evicted first when a serving pod needs room."\nEOF\n'})}),"\n",(0,r.jsx)(s.p,{children:(0,r.jsx)(s.strong,{children:"Expected output"})}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-text",children:"priorityclass.scheduling.k8s.io/model-serving created\npriorityclass.scheduling.k8s.io/batch-inference created\n"})}),"\n",(0,r.jsxs)(s.p,{children:["Attaching ",(0,r.jsx)(s.code,{children:"priorityClassName: model-serving"})," to the model Deployment's pod template means that when the cluster is under pressure, the scheduler evicts ",(0,r.jsx)(s.code,{children:"batch-inference"})," pods before it touches OpsMate. Confirm the classes registered and their values:"]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-bash",children:"kubectl --kubeconfig labs/opsmate/k8s/kubeconfig get priorityclass model-serving batch-inference\n"})}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Expected output"})," (the two classes with their priority values; the ",(0,r.jsx)(s.code,{children:"PREEMPTIONPOLICY"})," column and ",(0,r.jsx)(s.code,{children:"AGE"})," are point-in-time)"]}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-text",children:"NAME              VALUE     GLOBAL-DEFAULT   AGE   PREEMPTIONPOLICY\nmodel-serving     1000000   false            0s    PreemptLowerPriority\nbatch-inference   1000      false            0s    PreemptLowerPriority\n"})}),"\n",(0,r.jsxs)(s.p,{children:["The subtlety that matters for model pods specifically: preemption is ",(0,r.jsx)(s.em,{children:"disruptive"}),", and a model pod that gets preempted pays the full ~40 s reload cost when it reschedules elsewhere. So PriorityClass protects your serving pods from ",(0,r.jsx)(s.em,{children:"being"})," preempted (good), but you also want a ",(0,r.jsx)(s.code,{children:"PodDisruptionBudget"})," so voluntary disruptions (node drains, upgrades) do not take all your replicas at once \u2014 the reload cost makes model pods more expensive to disrupt than a stateless service. M11 builds the autoscaling-plus-priority story in full; here you have the mechanism and the model-serving-specific reason it matters."]}),"\n",(0,r.jsx)(s.p,{children:"Clean up the deep-dive resources (leave the model server running if you are continuing):"}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-bash",children:"kubectl --kubeconfig labs/opsmate/k8s/kubeconfig delete priorityclass model-serving batch-inference\n"})}),"\n",(0,r.jsx)(s.p,{children:(0,r.jsx)(s.strong,{children:"Expected output"})}),"\n",(0,r.jsx)(s.pre,{children:(0,r.jsx)(s.code,{className:"language-text",children:"priorityclass.scheduling.k8s.io/model-serving deleted\npriorityclass.scheduling.k8s.io/batch-inference deleted\n"})}),"\n",(0,r.jsx)(s.h2,{id:"where-you-will-use-this",children:"Where you will use this"}),"\n",(0,r.jsxs)(s.p,{children:["The startupProbe math is what you reach for the first time a model pod dies just under its load budget on a slow node \u2014 you will know to check timeout-versus-failure rather than blindly bumping numbers. The Service-backpressure picture is the reason M9's replica and M11's autoscaler watch ",(0,r.jsx)(s.code,{children:"requests_deferred"})," and not ",(0,r.jsx)(s.code,{children:"/health"}),", and it is what you will explain in a review when someone proposes a readiness probe that sheds load. The GPU survey is the vocabulary you need the day OpsMate moves off CPU \u2014 time-slicing for the dev cluster, MIG for the production tenants. And PriorityClass is the M11 setup: when a batch job and your inference server want the same node, priority decides, and the ~40 s reload cost is why model pods sit at the top."]})]})}function c(e={}){let{wrapper:s}={...(0,i.R)(),...e.components};return s?(0,r.jsx)(s,{...e,children:(0,r.jsx)(h,{...e})}):h(e)}},8453(e,s,t){t.d(s,{R:()=>a,x:()=>o});var n=t(6540);let r={},i=n.createContext(r);function a(e){let s=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(s):{...s,...e}},[s,e])}function o(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),n.createElement(i.Provider,{value:s},e.children)}}}]);